--- 最上方的tab标签页的逻辑
-----

------------ import ------------
local UIEventProxy = CS.Engine.UI.UIEventProxy
local KTool = CS.Engine.Lib.KTool
local XLuaUtils = CS.Engine.Lib.XLuaUtils
local ID = CS.Game.Native.Common.ID
local Text = CS.UnityEngine.UI.Text
local GridLayoutGroup = CS.UnityEngine.UI.GridLayoutGroup
------------ import ------------

------------ define ------------
local LeftPadding = 0
------------ define ------------

---@class CommonTopTabNode
---@field TabGroup                      	UnityEngine.RectTransform @TabGroup对象
---@field FlowImage                  	UnityEngine.RectTransform 浮动条图片
local CommonTopTabNode = Class('CommonTopTabNode')

function CommonTopTabNode:__init()
    self._tabId = 1
    self.cb = nil
    self._isFlowing = false
    self._cellWidth = 0
end

function CommonTopTabNode:__delete()
    self.cb = nil
    self._cellWidth = 0
    self._tabId = nil
    self._isFlowing = false
end

function CommonTopTabNode:Start()
    LeftPadding = self.FlowImage.anchoredPosition.x
    ---@type UnityEngine.RectTransform
    local tabTrans = self.TabGroup
    ---@type UnityEngine.UI.GridLayoutGroup
    local gridLayoutGroup = KTool.GetComponent(tabTrans.gameObject, typeof(GridLayoutGroup))
    self._cellWidth = gridLayoutGroup.cellSize.x
    local length = tabTrans.childCount
    ---添加子节点的点击事件
    for i = 1, length do
        local childTrans = tabTrans:GetChild(i - 1)
        if childTrans then
            UIEventProxy.Create(childTrans.gameObject).onPointerClick = Bind(self, self.OnTabButtonAction)
        end
    end
    self:OnSelectTabButton(1, true)
end

---OnSelectTabButton
---某个标签被选中
---@param id number
function CommonTopTabNode:OnSelectTabButton(id, initialize)
    initialize = checkBool(initialize)
    local position = self.FlowImage.anchoredPosition
    local x = LeftPadding + (id - 1) *  self._cellWidth
    ---更新按钮的选中状态
    self._isFlowing = true
    self.FlowImage:DOAnchorPos3D(Vector3.New(x, position.y, 0), 0.12).onComplete = function()
        ---是否完成后执行功能
        self._isFlowing = false
        if self.cb and (not initialize) then
            self.cb(id)
        end
    end
    ---@type UnityEngine.RectTransform
    local tabTrans = self.TabGroup
    local length = tabTrans.childCount
    ---添加子节点的点击事件
    for i = 1, length do
        ---@type UnityEngine.RectTransform
        local childTrans = tabTrans:GetChild(i - 1)
        if childTrans then
            local gId = KTool.GetComponent(childTrans.gameObject, typeof(ID)).id
            local textTrans = childTrans:Find("Text")
            ---@type UnityEngine.UI.Text
            local textComp = KTool.GetComponent(textTrans.gameObject, typeof(Text))
            if gId == id then
                ---选中的节点
                textComp.color = XLuaUtils.HexToColor('#fdbb25')
                textComp.fontSize = 24
            else
                ---未选中的节点
                textComp.color = XLuaUtils.HexToColor('#858074')
                textComp.fontSize = 22
            end
        end
    end
end

function CommonTopTabNode:SetTabTexts(t)
    ---@type UnityEngine.RectTransform
    local tabTrans = self.TabGroup
    local length = tabTrans.childCount
    local sourceLen = #t
    ---添加子节点的点击事件
    for i = 1, length do
        ---@type UnityEngine.RectTransform
        local childTrans = tabTrans:GetChild(i - 1)
        if childTrans then
            local textTrans = childTrans:Find("Text")
            ---@type UnityEngine.UI.Text
            local textComp = KTool.GetComponent(textTrans.gameObject, typeof(Text))
            if i <= sourceLen then
                textComp.text = t[i] or ''
            else
                KTool.SetActive(childTrans.gameObject, false)
            end
                --textComp.color = XLuaUtils.HexToColor('#858074')
                --textComp.fontSize = 22
        end
    end
end

---OnTabButtonAction
--- tab的按钮点击的事件
---@param eventData UnityEngine.EventSystems.PointerEventData
function CommonTopTabNode:OnTabButtonAction(eventData)
    local id = KTool.GetComponent(eventData.pointerCurrentRaycast.gameObject, typeof(ID)).id
    if not self._isFlowing then
        if self._tabId == id then
            return
        end
        self._tabId = id
        self:OnSelectTabButton(id)
    end
end


function CommonTopTabNode:SetCallbackAction(cb)
    self.cb = cb

end

function CommonTopTabNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return CommonTopTabNode